"""Generated by the NL to Flow Diagram Encoder Pipeline."""

class LRUCache:
    def __init__(self, capacity):
        self.given_capacity = capacity
        self.cache = {}
        self.order = []

    def get(self, key):
        if (key not in self.cache):
            return (-1)
            # or NULL
            # Move key to front of order (most recently used)
        self.order.remove(key)
        self.order.insert(0, key)
        return self.cache[key]

    def put(self, key, value):
        if (key in self.cache):
            # Update value and move key to front
            self.cache[key] = value
            self.order.remove(key)
            self.order.insert(0, key)
        else:
            if (len(self.order) >= self.given_capacity):
                # Evict the least recently used (last element in order)
                lruKey = self.order[(-1)]
                self.order.pop()
                self.cache.pop(lruKey)
            self.order.insert(0, key)
            self.cache[key] = value

# Create cache with capacity 2
cache = LRUCache(2)

cache.put(1, 100)   # cache = {1:100}, order = [1]
cache.put(2, 200)   # cache = {1:100, 2:200}, order = [2,1]

print(cache.get(1))  # 100, order = [1,2]

cache.put(3, 300)    # Evicts key 2 (LRU)
                     # cache = {1:100, 3:300}, order = [3,1]

print(cache.get(2))  # -1 (evicted)
print(cache.get(3))  # 300, order = [3,1]

cache.put(4, 400)    # Evicts key 1
                     # cache = {3:300, 4:400}, order = [4,3]

print(cache.get(1))  # -1
print(cache.get(3))  # 300
print(cache.get(4))  # 400
